import React from 'react';

const About = () => {
    const sectionStyle = {
        padding: '2rem',
        backgroundColor: '#f9f9f9',
        borderRadius: '8px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        maxWidth: '800px',
        margin: '2rem auto',
        fontFamily: 'Arial, sans-serif',
        lineHeight: '1.6',
    };

    const headingStyle = {
        fontSize: '2rem',
        color: '#333',
        marginBottom: '1rem',
        textAlign: 'center',
    };

    const paragraphStyle = {
        fontSize: '1.2rem',
        color: '#555',
        textAlign: 'justify',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>About Me</h1>
            <p style={paragraphStyle}>
                Hi, I am <strong>[Your Name]</strong>, a <strong>[Your Profession]</strong>. I am passionate about 
                <strong> [your hobbies/interests]</strong>. I enjoy learning new things and working on exciting projects.
            </p>
        </section>
    );
};

export default About;
